// parity_test.cpp — Fase A do docs/CPP_STRATEGY.md.
//
// Replays native/cpp/corpus.txt (generated by tests/world-rhythm-corpus.test.ts
// from the REAL TypeScript worldRhythm) against this C++ port. Any divergence
// between TS and C++ is printed with the exact corpus line and the program
// exits non-zero — so the WASM nucleus is only trusted while this is green.
//
// Build & run:
//   g++ -std=c++17 -O2 -Wall -Wextra -o parity_test parity_test.cpp world_rhythm.cpp
//   ./parity_test                 # reads corpus.txt from the cwd

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>

#include "world_rhythm.h"

int main(int argc, char** argv) {
  const char* corpus_path = (argc > 1) ? argv[1] : "corpus.txt";
  std::ifstream in(corpus_path);
  if (!in) {
    std::fprintf(stderr, "nao consigo abrir o corpus: %s\n", corpus_path);
    return 2;
  }

  int parsed = 0;
  int mismatches = 0;
  int line_no = 0;
  std::string line;

  while (std::getline(in, line)) {
    ++line_no;
    if (line.empty() || line[0] == '#') continue;

    std::istringstream ss(line);
    std::string world_name, phase_name;
    int64_t minutes, ev_start, ev_end, mood, next_start, next_end;
    if (!(ss >> world_name >> minutes >> phase_name >> ev_start >> ev_end >> mood >>
          next_start >> next_end)) {
      std::printf("LINHA %d ilegivel: %s\n", line_no, line.c_str());
      ++mismatches;
      continue;
    }

    const guinomo::World world = guinomo::ParseWorld(world_name);
    if (world == guinomo::World::kUnknown) {
      std::printf("LINHA %d mundo desconhecido, ignorada: %s\n", line_no, world_name.c_str());
      continue;
    }
    ++parsed;

    bool ok = true;

    // phase
    const std::string got_phase = guinomo::DayPhaseName(guinomo::PhaseOf(minutes));
    if (got_phase != phase_name) {
      std::printf("LINHA %d [phase] %s@%lld: esperado '%s', C++ deu '%s'\n", line_no,
                  world_name.c_str(), static_cast<long long>(minutes), phase_name.c_str(),
                  got_phase.c_str());
      ok = false;
    }

    // event window
    const guinomo::WorldEvent ev = guinomo::EventAt(world, minutes);
    const int64_t got_ev_start = ev.active ? ev.start : -1;
    const int64_t got_ev_end = ev.active ? ev.end : -1;
    if (got_ev_start != ev_start || got_ev_end != ev_end) {
      std::printf("LINHA %d [event] %s@%lld: esperado %lld..%lld, C++ deu %lld..%lld\n", line_no,
                  world_name.c_str(), static_cast<long long>(minutes),
                  static_cast<long long>(ev_start), static_cast<long long>(ev_end),
                  static_cast<long long>(got_ev_start), static_cast<long long>(got_ev_end));
      ok = false;
    }

    // mood
    const int64_t got_mood = guinomo::WorldMood(world, minutes);
    if (got_mood != mood) {
      std::printf("LINHA %d [mood] %s@%lld: esperado %lld, C++ deu %lld\n", line_no,
                  world_name.c_str(), static_cast<long long>(minutes),
                  static_cast<long long>(mood), static_cast<long long>(got_mood));
      ok = false;
    }

    // next window
    const guinomo::WorldEvent nx = guinomo::NextEvent(world, minutes);
    const int64_t got_next_start = nx.active ? nx.start : -1;
    const int64_t got_next_end = nx.active ? nx.end : -1;
    if (got_next_start != next_start || got_next_end != next_end) {
      std::printf("LINHA %d [next] %s@%lld: esperado %lld..%lld, C++ deu %lld..%lld\n", line_no,
                  world_name.c_str(), static_cast<long long>(minutes),
                  static_cast<long long>(next_start), static_cast<long long>(next_end),
                  static_cast<long long>(got_next_start), static_cast<long long>(got_next_end));
      ok = false;
    }

    if (!ok) ++mismatches;
  }

  std::printf("parity: %d linhas validas, %d divergencias\n", parsed, mismatches);
  return mismatches == 0 ? 0 : 1;
}